import json, sys
for line in sys.stdin:
    request = json.loads(line)
    if 'id' not in request:
        continue
    method = request['method']
    if method == 'initialize':
        result = {'protocolVersion': request['params']['protocolVersion'], 'capabilities': {'tools': {}}, 'serverInfo': {'name': 'docs', 'version': '1'}}
    elif method == 'tools/list':
        result = {'tools': [{'name': 'search', 'description': 'Search documents', 'inputSchema': {'type': 'object', 'properties': {'query': {'type': 'string'}}, 'required': ['query'], 'additionalProperties': False}}]}
    elif method == 'tools/call':
        assert request['params']['name'] == 'search'
        result = {'content': [], 'structuredContent': request['params']['arguments'], 'isError': False}
    else:
        raise RuntimeError(method)
    print(json.dumps({'jsonrpc': '2.0', 'id': request['id'], 'result': result}), flush=True)
